from pathlib import Path
import shutil,re,wave,struct,math
out=Path('artifacts/rest-edits-report');(out/'assets').mkdir(parents=True,exist_ok=True)
source=Path('app/e2e/qol-audit/rest-edits')
for name in ['edit-active.png','edited-active.png','sound-settings.png','edited-history.png','rest-chime.wav']:shutil.copy(source/name,out/'assets'/name)
shutil.copy('artifacts/mobile-ux-report/assets/after-workout.png',out/'assets/earlier-workout.png')
shutil.copy('app/public/fonts/anton.woff2',out/'assets/anton.woff2')
favicon=re.search(r'<link rel="icon"[^>]+>',Path('artifacts/mobile-ux-report/index.html').read_text()).group()
with wave.open(str(out/'assets/rest-chime.wav')) as f:
 samples=struct.unpack('<'+'h'*f.getnframes(),f.readframes(f.getnframes()))
heights=[max(3,round(max(abs(v) for v in samples[i*len(samples)//64:(i+1)*len(samples)//64])/4200*70)) for i in range(64)]
bars=''.join(f'<i style="height:{h}px"></i>' for h in heights)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Explain(gz): Rest chime & edited sets</title>'''+favicon+'''<link rel="stylesheet" href="style.css"><script src="report.js" defer></script></head><body><header><a href="#">GYM ZERO <span>/ SMALL DETAILS, BETTER SESSIONS</span></a><a href="https://pages.subir.dev/e62ce31d-1cf2-4839-954d-582a8981ca20/">Muscle-map walkthrough ↗</a></header><main><section class="hero"><div><p class="eyebrow">IMPLEMENTED / REST SOUND + SET CORRECTIONS</p><h1>A GENTLE DING.<br>THE RIGHT REPS<span>.</span></h1><p class="lead">Hear when rest is over. Correct what you actually did. Keep a visible record that the numbers changed.</p><a class="primary" href="#listen">Hear the chime ↓</a><a class="secondary" href="#screens">See the changes ↓</a><p class="fine">Implemented and tested locally. This page publishes the walkthrough, screenshots, and sound preview; it does not deploy the application.</p></div><div class="demo"><p class="eyebrow">TRY A CORRECTION</p><p class="fine">Illustrative UI — does not change your workout.</p><h3>LEG PRESS</h3><div class="demo-set"><span>SET 1</span><b>90 lb × <span id="saved-reps">10</span> reps</b><span id="edited-label" hidden>Edited</span></div><label for="demo-reps">What you actually did</label><div class="demo-entry"><input id="demo-reps" type="number" inputmode="numeric" min="1" step="1" value="14"><button id="demo-save">Save changes</button></div><p id="demo-status" role="status">Originally logged as 10 reps.</p><button class="text-button" id="demo-reset">Reset demo</button></div></section><nav aria-label="Report sections"><a href="#listen">Chime</a><a href="#workflow">Editing</a><a href="#screens">Screenshots</a><a href="#details">What changed</a><a href="#checks">Checks</a><a href="#qa">Q&A</a></nav>
<section id="listen"><p class="eyebrow">01 / LISTEN FIRST</p><h2>Short. Soft. Once.</h2><p class="intro">Two rounded notes, a gentle onset, and a quick fade. No repeating alarm, sharp buzzer, or system-volume change.</p><div class="audio-card"><div class="waveform" aria-hidden="true">'''+bars+'''</div><audio controls preload="metadata" src="assets/rest-chime.wav" aria-label="Preview the Gym Zero rest-complete chime">Your browser does not support audio playback. <a href="assets/rest-chime.wav">Download the chime</a>.</audio><p class="fine">Exact app audio graph rendered to WAV · about 1.6 seconds of sound · your device’s media volume applies.</p></div><div class="two"><article><h3>When it plays</h3><p>Once when the rest timer reaches zero. It works while moving between app tabs. Editing a saved set does not restart the timer. Skipping rest is silent.</p></article><article><h3>You control it</h3><p>Settings → Rest timer sound → Sound on/off. The choice persists after reload. Preview chime lets you try the sound even when automatic completion sound is off.</p></article></div><p class="note">Keep the app open. Phone locking, background suspension, browser audio restrictions, and device volume can prevent a timely or audible chime. Existing visual completion feedback remains.</p></section>
<section id="workflow"><p class="eyebrow">02 / CORRECT YOUR NUMBERS</p><h2>Already saved?<br>You can still fix it.</h2><div class="two"><article><span class="step">DURING A WORKOUT</span><h3>Edit the saved set</h3><ol><li>Tap <b>Edit set</b> below the logged row.</li><li>Change reps or weight.</li><li>Tap <b>Save changes</b>.</li></ol><p>The row updates and gains an Edited label. The set stays part of the same workout, and rest keeps its existing countdown.</p></article><article><span class="step">AFTER A WORKOUT</span><h3>Open it from Stats</h3><ol><li>Go to <b>Stats → Sessions</b>.</li><li>Tap <b>Review / edit sets</b>.</li><li>Under Logged sets, edit the relevant row.</li></ol><p>The workout date and available station names help identify the right session/set. Totals and highlights refresh after saving.</p></article></div><div class="note"><b>What “Edited” means</b><p>The values changed after the set was logged. The label stays visible after reload. Opening the editor shows the latest edit time and the original weight/reps. Saving unchanged values does not create an edit marker.</p></div></section>
<section id="screens"><p class="eyebrow">03 / ACTUAL PHONE-SIZED SCREENS</p><h2>Visible feedback,<br>from edit to history.</h2><p class="intro">Current screenshots use sample workouts in a 390 × 844 browser viewport. Tap any image to enlarge it.</p>'''
def shot(name,label):return f'<figure><figcaption>{label}</figcaption><button class="shot" data-src="assets/{name}.png" data-label="{label}"><img src="assets/{name}.png" width="390" height="844" loading="lazy" alt="{label}"></button></figure>'
html+='<div class="pair">'+shot('earlier-workout','EARLIER SAVED-SET UI')+shot('edited-active','CURRENT · EDITED LABEL')+'</div>'
html+='''<p class="fine">The earlier image is an actual screenshot from the previous QoL audit. It uses a different sample session and predates the muscle-map feature, so this is historical UI context rather than a matched-data capture. It had no explicit set-edit action or Edited marker.</p><div class="pair">'''+shot('edit-active','CORRECT REPS OR WEIGHT')+shot('edited-history','EDIT FINISHED WORKOUTS')+'</div><div class="settings-shot">'+shot('sound-settings','REST SOUND SETTINGS · SHOWN TURNED OFF')+'''<div><h3>A preview before you decide.</h3><p>The sound setting is on by default, including for existing installations. This screenshot shows it turned off to demonstrate the saved preference. Preview remains available.</p><p>Audio is prepared on a user tap or key press, before the asynchronous save finishes. This gives mobile browsers a chance to authorize sound before the timer ends.</p><p class="fine">No audio file download or new package is required by the app. The downloadable WAV on this report is a preview of the same generated sound.</p></div></div></section>
<section id="details"><p class="eyebrow">04 / IMPLEMENTATION DETAILS</p><h2>Corrected values.<br>Preserved history.</h2><ul class="changes"><li><b>Soft chime.</b> A Web Audio module creates two sine notes with a gradual attack/fade. Nodes disconnect when finished, and rapid preview taps do not stack overlapping chimes.</li><li><b>Reliable completion behavior.</b> The timer reads the current sound preference when it completes, including preference changes made during rest. The countdown now uses ceiling rounding so it does not finish roughly half a second early.</li><li><b>Reusable editor.</b> One labeled, mobile-friendly form serves active and completed sessions. Rep input is selected for quick replacement. Cancel leaves saved values alone; invalid, unchanged, or busy saves are disabled.</li><li><b>Persistent edit metadata.</b> The set stores <code>editedAt</code> and its first <code>originalValues</code>. Subsequent edits retain those original values. This is an original/latest record, not a complete revision-by-revision history.</li><li><b>Set identity preserved.</b> Correcting weight/reps retains the set ID, workout ID, exercise ID, machine ID, set number, and original logging time. Workout finish time stays unchanged.</li><li><b>Current totals.</b> The completed-workout summary reloads its totals and highlights after an edit. History/weekly views read the corrected records when reopened.</li><li><b>Strength suggestions corrected.</b> If the old set values supplied the stored strength baseline, that baseline is recalculated from remaining valid sets. A higher corrected set can update an existing baseline.</li><li><b>Atomic data update.</b> Validation and writes run in a transaction. A stale editor cannot silently overwrite a different correction; it asks for a reload. Duplicate save taps are guarded.</li><li><b>Existing data compatibility.</b> Old sets have no edit marker until changed. Optional metadata travels with existing backup and sync records. The backup round-trip is tested; live multi-device sync was not tested.</li><li><b>Past sessions made accessible.</b> Stats session cards now expose Review / edit sets. The summary displays the session date, grouped saved sets, station names when available, and paths back to Stats.</li></ul><details><summary>Files changed for this addition</summary><ul class="file-list"><li><code>app/src/lib/rest-chime.ts</code> — new audio synthesis and browser priming.</li><li><code>app/src/components/SetEditor.tsx</code> — new shared edit form and Edited label.</li><li><code>app/src/App.tsx</code> — audio priming and completion trigger.</li><li><code>app/src/screens/Settings.tsx</code> — sound preference and preview.</li><li><code>app/src/screens/Workout.tsx</code> — active-set editing and guards.</li><li><code>app/src/screens/Summary.tsx</code> — completed-set editing, grouped records, refreshed totals, date/loading recovery.</li><li><code>app/src/screens/History.tsx</code> — discoverable review/edit action.</li><li><code>app/src/data/index.ts</code> — validated transactional update and baseline correction.</li><li><code>app/src/types.ts</code> — sound preference, edit metadata, update API.</li><li><code>app/src/styles.css</code> — mobile editor, labels, and sound controls.</li><li><code>app/e2e/rest-edits.mjs</code> — new audio/edit regression suite and preview capture.</li><li><code>app/e2e/flow.mjs</code> — scope set-progress assertions to the intended exercise.</li><li><code>app/package.json</code> — add <code>e2e:rest-edits</code>.</li><li><code>README.md</code> — behavior, limits, and verification instructions.</li></ul></details></section>
<section id="checks"><p class="eyebrow">05 / VERIFICATION</p><h2>Checked in the browser.</h2><div class="checked"><b>PASS</b><p>Production build · full app walkthrough · QoL suite · machine-muscles suite · new rest-edits suite.</p></div><p>The new suite verifies a real browser AudioContext schedules one pair of notes at completion; Skip and muted completion do not play notes. It checks editing during and after a workout, cancel/no-op/invalid/conflicting saves, duplicate taps, preserved IDs and duration, refreshed volume, baseline correction, and backup persistence.</p><p>Editor layouts passed at 320, 375, 390, 430, and 1280px, with no audited overflow, at least 44px controls, and at least 16px input text.</p><p>The audio graph was also rendered offline: peak amplitude approximately 0.123 of full scale, RMS approximately 0.024, and a silent tail. These measurements confirm a low-level signal without clipping; perceived loudness and tone still depend on your device and preference.</p><p class="fine">Physical-phone speaker output, Safari audio policy, and locked/background playback have not been verified. Existing build notices remain for dependency annotations and a roughly 558KB JavaScript chunk. The application has not been deployed.</p></section>
<section id="qa"><p class="eyebrow">06 / Q&A</p><h2>A few useful distinctions.</h2><details><summary>Can I correct only the reps?</summary><p>Yes. Leave weight as it is, change reps, and save. You can also correct both values.</p><p class="fine">Why this matters: forgetting the actual rep count is the main reason for this feature.</p></details><details><summary>Will an edit start another rest timer?</summary><p>No. Only logging a new set starts rest. Correcting an existing set leaves the current timer alone.</p><p class="fine">Why this matters: an administrative correction should not interrupt the training rhythm.</p></details><details><summary>Will editing an old session make it look longer?</summary><p>No. Its original finish time and duration are preserved. Volume and highlights use the corrected numbers.</p><p class="fine">Why this matters: fixing reps should not rewrite when the workout happened.</p></details><details><summary>Can I see every past revision?</summary><p>The app retains the original values and the latest edit time, with the current values on the row. It does not keep a full list of every intermediate change.</p><p class="fine">Why this matters: an Edited marker is useful without promising a full audit-history system.</p></details><details><summary>Will I hear the chime with the phone locked?</summary><p>That is not guaranteed. Keep the app open; a suspended browser may not run the timer/audio promptly. The sound also follows device media volume and browser restrictions.</p><p class="fine">Why this matters: this is an in-app rest cue, not a native background alarm.</p></details></section><footer><b>GYM ZERO</b><p>Rest chime & saved-set corrections · September 2026</p><a href="#listen">Play the chime ↑</a></footer></main><dialog id="zoom"><div><span id="zoom-label"></span><button id="close">Close ×</button></div><img id="zoom-img" alt=""></dialog></body></html>'''
(out/'index.html').write_text(html)
print('Built rest/edit walkthrough with sound preview and five screenshots.')
